import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3003';
const WS_URL = 'ws://localhost:3003';

interface InventoryItem {
    BloodType: string;
    TotalBags: number;
}

const InventoryStats = () => {
    const [inventory, setInventory] = useState<InventoryItem[] | null>(null);
    const [error, setError] = useState<string | null>(null);

    const fetchInventory = async () => {
        try {
            const response = await axios.get<InventoryItem[]>(`${API_URL}/inventory`);
            setInventory(response.data);
        } catch (err) {
            setError('Failed to fetch inventory stats.');
            console.error(err);
        }
    };

    useEffect(() => {
        fetchInventory();
        const ws = new WebSocket(WS_URL);
        ws.onmessage = (event) => {
            const message = JSON.parse(event.data);
            if (message.type === 'new_update') {
                fetchInventory();
            }
        };
        return () => ws.close();
    }, []);

    if (error) return <div className="alert error">{error}</div>;
    if (!inventory) return <div>Loading stats...</div>;

    const totalBags = inventory.reduce((sum, item) => sum + item.TotalBags, 0);

    return (
        <div className="inventory-stats">
            <h3>Inventory Statistics</h3>
            <p><strong>Total Bags:</strong> {totalBags}</p>
            <h4>Bags by Blood Type:</h4>
            <ul>
                {inventory.map((item) => (
                    <li key={item.BloodType}>{(item.BloodType && item.BloodType !== 'null') ? item.BloodType : 'N/A'}: {item.TotalBags}</li>
                ))}
            </ul>
        </div>
    );
};

export default InventoryStats;
